func (bw *bufferedResponseWriter) Write(data []byte) (int, error) {
	bw.WriteHeader(http.StatusOK)
	if room := maxBufferedAuthResponse - bw.buf.Len(); room < len(data) {
		bw.overflowed = true
		if room > 0 {
