    /**
     * Rewrites case-insensitive and abbreviated special values ({@code nan}, {@code inf}, {@code
     * infinity}, with an optional sign on infinity) into the canonical tokens {@link
     * Double#parseDouble} and {@link Float#parseFloat} accept. Any other input is returned
     * unchanged.
     */
    private static String normalizeFloatingPointSpecialValue(String str) {
        final String trimmed = str.trim();
        if (trimmed.equalsIgnoreCase("nan")) {
            return "NaN"; // NaN is unsigned, so a signed token is left to fail
        }
        String sign = "";
        String magnitude = trimmed;
        if (!trimmed.isEmpty() && (trimmed.charAt(0) == '+' || trimmed.charAt(0) == '-')) {
            sign = trimmed.substring(0, 1);
            magnitude = trimmed.substring(1);
        }
        if (magnitude.equalsIgnoreCase("infinity") || magnitude.equalsIgnoreCase("inf")) {
            return sign + "Infinity";
        }
        return str;
    }

