    pub fn auto_vacuum(&mut self, schema: Option<&str>) -> QueryResult<AutoVacuumMode> {
        use crate::query_dsl::RunQueryDsl;
        let query: Pragma<'_, crate::sql_types::Integer> = Pragma::new("auto_vacuum", schema);
