+import {Routes, nonBlocking} from '@angular/router';
+
+const routes: Routes = [
+  {
+    path: 'reports',
+    component: Reports,
+    resources: (ctx) => ({
+      reportData: nonBlocking(
+        resource({
+          loader: () => fetchHeavyReportData(),
+        }),
+      ),
+    }),
+  },
+];
